package com.clavis.reader;
import android.content.*;import android.widget.*;import java.io.*;
/** Entries exchange private session files rather than large Binder extras. */
final class Listen {
 static void article(MainActivity a,String key,String title,String text){if(text.trim().isEmpty()){AppNotice.makeText(a,"No story text to read yet. Wait for the story to load.",Toast.LENGTH_LONG).show();return;}android.app.ProgressDialog progress=new android.app.ProgressDialog(a);progress.setMessage("Preparing story…");progress.setCancelable(false);progress.show();a.io.execute(()->{try{ListenSession story=new ListenSession(key,title,NarrationText.clean(text));File file=ListenSession.file(a,key);story.save(file);a.runOnUiThread(()->{progress.dismiss();if(!a.isFinishing()&&!a.isDestroyed())open(a,file);});}catch(Exception e){a.runOnUiThread(()->{progress.dismiss();AppNotice.makeText(a,"Could not prepare reading: "+e.getMessage(),Toast.LENGTH_LONG).show();});}});}
 static void open(Context c,File file){if(c instanceof ReaderActivity){((ReaderActivity)c).startInlineListen(file);return;}try{ListenSession session=ListenSession.read(file);if(session.key.startsWith("book:")){int end=session.key.lastIndexOf(':');String uri=session.key.substring(5,end);for(Book book:Store.load(c))if(book.uri.equals(uri)||book.epubUri.equals(uri)){c.startActivity(new Intent(c,ReaderActivity.class).putExtra("uri",uri).putExtra("title",book.title).putExtra("kind",book.epubUri.equals(uri)?"EPUB":book.author).putExtra("listenFile",file.getAbsolutePath()));return;}}}catch(Exception ignored){}c.startActivity(new Intent(c,ListenActivity.class).putExtra("file",file.getAbsolutePath()));}
 static void effects(MainActivity a){ListenService service=ListenService.live;if(service==null||service.track==null){AppNotice.makeText(a,"Start listening first",Toast.LENGTH_SHORT).show();return;}service.ensureEffects();PlayerDialogs.effects(a,service.equalizer,service.loudness);}
 static void voiceSettings(MainActivity a){ListenService service=ListenService.live;if(service==null)return;new AppDialog.Builder(a).setTitle("Narrator voice").setSingleChoiceItems(new String[]{"Male · Hugo","Original voice"},service.speaker,(dialog,n)->{if(ListenService.live==service)service.setVoice(n);dialog.dismiss();}).setPositiveButton(service.ready?"Close":"Download voices",(dialog,n)->{if(!service.ready)service.downloadVoice();}).show();}
 static void resume(MainActivity a){String last=a.getSharedPreferences("listen",0).getString("last","");if(last.isEmpty()){AppNotice.makeText(a,"Open a book or story and choose Listen first.",Toast.LENGTH_SHORT).show();return;}open(a,new File(last));}
}
